window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2183ccd2503e7934"]={"versions": [{"id": "FIG-2183ccd2503e7934", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR-Metamodell-Spezifikation (TPS_StandardizationTemplate). Es illustriert das Blueprint-Muster am Beispiel von <code>PortInterface</code>, bei dem dieselbe Metaklasse sowohl als Vorlage (<code>AtpBlueprint</code>) als auch als abgeleitetes Element (<code>AtpBlueprintable</code>) fungiert, sowie deren Verknüpfung über das generische und das konkrete Blueprint-Mapping.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>AtpBlueprintMapping</code>: Abstrakte Metaklasse für das Mapping zwischen Blueprints und abgeleiteten Objekten.</li>\n<li>Assoziation <code>+/atpBlueprint 1</code> («atpAbstract,atpUriDef») zu <code>AtpBlueprint</code>.</li>\n<li>Assoziation <code>+/atpBlueprintedElement 1</code> («atpAbstract») zu <code>AtpBlueprintable</code>.</li>\n<li><code>BlueprintMapping</code>: Konkrete Spezialisierung von <code>AtpBlueprintMapping</code>.</li>\n<li>Assoziation <code>+blueprint 1 {redefines atpBlueprint}</code> zu <code>AtpBlueprint</code>.</li>\n<li>Assoziation <code>+derivedObject 1 {redefines atpBlueprintedElement}</code> zu <code>AtpBlueprintable</code>.</li>\n<li><code>AtpBlueprint</code>: Abstraktes Konzept (spezialisiert <code>Identifiable</code>), Ziel der Blueprint-Referenz.</li>\n<li><code>AtpBlueprintable</code>: Abstraktes Konzept (spezialisiert <code>Identifiable</code>), Ziel der Referenz auf das abgeleitete Objekt.</li>\n<li><code>PortInterface</code>: Konkrete Metaklasse (spezialisiert <code>ARElement</code>, <code>AtpType</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>).</li>\n<li>Attribute:</li>\n<li><code>+ isService: Boolean</code></li>\n<li><code>+ serviceKind: ServiceProviderEnum [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamischer Ablauf oder Sequenzverhalten dargestellt. Die Beziehungen definieren die strukturelle Bindung, mit der ein konkretes <code>BlueprintMapping</code> eine Instanz von <code>PortInterface</code> in der Rolle des Blueprints (<code>blueprint</code>) mit einer Instanz von <code>PortInterface</code> in der Rolle des abgeleiteten Objekts (<code>derivedObject</code>) verknüpft.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Muster für Werkzeughersteller und Standardisierer: <code>PortInterface</code> implementiert gleichzeitig <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Ein konkretes <code>BlueprintMapping</code> bindet per Redefinition die abstrakten Metarollen <code>atpBlueprint</code> und <code>atpBlueprintedElement</code> jeweils mit Kardinalität 1 an die Schnittstelleninstanzen. Attribut <code>isService</code> ist obligatorisch (<code>Boolean</code>), <code>serviceKind</code> ist optional (<code>[0..1]</code>).</p>"}, {"id": "FIG-f24e73811509874a", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR-Metamodell-Spezifikation (TPS_StandardizationTemplate). Es illustriert das Blueprint-Muster am Beispiel von <code>PortInterface</code>, bei dem dieselbe Metaklasse sowohl als Vorlage (<code>AtpBlueprint</code>) als auch als abgeleitetes Element (<code>AtpBlueprintable</code>) fungiert, sowie deren Verknüpfung über das generische und das konkrete Blueprint-Mapping.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>AtpBlueprintMapping</code>: Abstrakte Metaklasse für das Mapping zwischen Blueprints und abgeleiteten Objekten.</li>\n<li>Assoziation <code>+/atpBlueprint 1</code> («atpAbstract,atpUriDef») zu <code>AtpBlueprint</code>.</li>\n<li>Assoziation <code>+/atpBlueprintedElement 1</code> («atpAbstract») zu <code>AtpBlueprintable</code>.</li>\n<li><code>BlueprintMapping</code>: Konkrete Spezialisierung von <code>AtpBlueprintMapping</code>.</li>\n<li>Assoziation <code>+blueprint 1 {redefines atpBlueprint}</code> zu <code>AtpBlueprint</code>.</li>\n<li>Assoziation <code>+derivedObject 1 {redefines atpBlueprintedElement}</code> zu <code>AtpBlueprintable</code>.</li>\n<li><code>AtpBlueprint</code>: Abstraktes Konzept (spezialisiert <code>Identifiable</code>), Ziel der Blueprint-Referenz.</li>\n<li><code>AtpBlueprintable</code>: Abstraktes Konzept (spezialisiert <code>Identifiable</code>), Ziel der Referenz auf das abgeleitete Objekt.</li>\n<li><code>PortInterface</code>: Konkrete Metaklasse (spezialisiert <code>ARElement</code>, <code>AtpType</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>).</li>\n<li>Attribute:</li>\n<li><code>+ isService: Boolean</code></li>\n<li><code>+ serviceKind: ServiceProviderEnum [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamischer Ablauf oder Sequenzverhalten dargestellt. Die Beziehungen definieren die strukturelle Bindung, mit der ein konkretes <code>BlueprintMapping</code> eine Instanz von <code>PortInterface</code> in der Rolle des Blueprints (<code>blueprint</code>) mit einer Instanz von <code>PortInterface</code> in der Rolle des abgeleiteten Objekts (<code>derivedObject</code>) verknüpft.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Muster für Werkzeughersteller und Standardisierer: <code>PortInterface</code> implementiert gleichzeitig <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Ein konkretes <code>BlueprintMapping</code> bindet per Redefinition die abstrakten Metarollen <code>atpBlueprint</code> und <code>atpBlueprintedElement</code> jeweils mit Kardinalität 1 an die Schnittstelleninstanzen. Attribut <code>isService</code> ist obligatorisch (<code>Boolean</code>), <code>serviceKind</code> ist optional (<code>[0..1]</code>).</p>"}, {"id": "FIG-4f47c59dfb7666ef", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR-Metamodell-Spezifikation (TPS_StandardizationTemplate). Es illustriert das Blueprint-Muster am Beispiel von <code>PortInterface</code>, bei dem dieselbe Metaklasse sowohl als Vorlage (<code>AtpBlueprint</code>) als auch als abgeleitetes Element (<code>AtpBlueprintable</code>) fungiert, sowie deren Verknüpfung über das generische und das konkrete Blueprint-Mapping.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>AtpBlueprintMapping</code>: Abstrakte Metaklasse für das Mapping zwischen Blueprints und abgeleiteten Objekten.</li>\n<li>Assoziation <code>+/atpBlueprint 1</code> («atpAbstract,atpUriDef») zu <code>AtpBlueprint</code>.</li>\n<li>Assoziation <code>+/atpBlueprintedElement 1</code> («atpAbstract») zu <code>AtpBlueprintable</code>.</li>\n<li><code>BlueprintMapping</code>: Konkrete Spezialisierung von <code>AtpBlueprintMapping</code>.</li>\n<li>Assoziation <code>+blueprint 1 {redefines atpBlueprint}</code> zu <code>AtpBlueprint</code>.</li>\n<li>Assoziation <code>+derivedObject 1 {redefines atpBlueprintedElement}</code> zu <code>AtpBlueprintable</code>.</li>\n<li><code>AtpBlueprint</code>: Abstraktes Konzept (spezialisiert <code>Identifiable</code>), Ziel der Blueprint-Referenz.</li>\n<li><code>AtpBlueprintable</code>: Abstraktes Konzept (spezialisiert <code>Identifiable</code>), Ziel der Referenz auf das abgeleitete Objekt.</li>\n<li><code>PortInterface</code>: Konkrete Metaklasse (spezialisiert <code>ARElement</code>, <code>AtpType</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>).</li>\n<li>Attribute:</li>\n<li><code>+ isService: Boolean</code></li>\n<li><code>+ serviceKind: ServiceProviderEnum [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamischer Ablauf oder Sequenzverhalten dargestellt. Die Beziehungen definieren die strukturelle Bindung, mit der ein konkretes <code>BlueprintMapping</code> eine Instanz von <code>PortInterface</code> in der Rolle des Blueprints (<code>blueprint</code>) mit einer Instanz von <code>PortInterface</code> in der Rolle des abgeleiteten Objekts (<code>derivedObject</code>) verknüpft.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Muster für Werkzeughersteller und Standardisierer: <code>PortInterface</code> implementiert gleichzeitig <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Ein konkretes <code>BlueprintMapping</code> bindet per Redefinition die abstrakten Metarollen <code>atpBlueprint</code> und <code>atpBlueprintedElement</code> jeweils mit Kardinalität 1 an die Schnittstelleninstanzen. Attribut <code>isService</code> ist obligatorisch (<code>Boolean</code>), <code>serviceKind</code> ist optional (<code>[0..1]</code>).</p>"}, {"id": "FIG-6dbd3d7ed2d85c1b", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR-Metamodell-Spezifikation (TPS_StandardizationTemplate). Es illustriert das Blueprint-Muster am Beispiel von <code>PortInterface</code>, bei dem dieselbe Metaklasse sowohl als Vorlage (<code>AtpBlueprint</code>) als auch als abgeleitetes Element (<code>AtpBlueprintable</code>) fungiert, sowie deren Verknüpfung über das generische und das konkrete Blueprint-Mapping.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>AtpBlueprintMapping</code>: Abstrakte Metaklasse für das Mapping zwischen Blueprints und abgeleiteten Objekten.</li>\n<li>Assoziation <code>+/atpBlueprint 1</code> («atpAbstract,atpUriDef») zu <code>AtpBlueprint</code>.</li>\n<li>Assoziation <code>+/atpBlueprintedElement 1</code> («atpAbstract») zu <code>AtpBlueprintable</code>.</li>\n<li><code>BlueprintMapping</code>: Konkrete Spezialisierung von <code>AtpBlueprintMapping</code>.</li>\n<li>Assoziation <code>+blueprint 1 {redefines atpBlueprint}</code> zu <code>AtpBlueprint</code>.</li>\n<li>Assoziation <code>+derivedObject 1 {redefines atpBlueprintedElement}</code> zu <code>AtpBlueprintable</code>.</li>\n<li><code>AtpBlueprint</code>: Abstraktes Konzept (spezialisiert <code>Identifiable</code>), Ziel der Blueprint-Referenz.</li>\n<li><code>AtpBlueprintable</code>: Abstraktes Konzept (spezialisiert <code>Identifiable</code>), Ziel der Referenz auf das abgeleitete Objekt.</li>\n<li><code>PortInterface</code>: Konkrete Metaklasse (spezialisiert <code>ARElement</code>, <code>AtpType</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>).</li>\n<li>Attribute:</li>\n<li><code>+ isService: Boolean</code></li>\n<li><code>+ serviceKind: ServiceProviderEnum [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamischer Ablauf oder Sequenzverhalten dargestellt. Die Beziehungen definieren die strukturelle Bindung, mit der ein konkretes <code>BlueprintMapping</code> eine Instanz von <code>PortInterface</code> in der Rolle des Blueprints (<code>blueprint</code>) mit einer Instanz von <code>PortInterface</code> in der Rolle des abgeleiteten Objekts (<code>derivedObject</code>) verknüpft.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Muster für Werkzeughersteller und Standardisierer: <code>PortInterface</code> implementiert gleichzeitig <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Ein konkretes <code>BlueprintMapping</code> bindet per Redefinition die abstrakten Metarollen <code>atpBlueprint</code> und <code>atpBlueprintedElement</code> jeweils mit Kardinalität 1 an die Schnittstelleninstanzen. Attribut <code>isService</code> ist obligatorisch (<code>Boolean</code>), <code>serviceKind</code> ist optional (<code>[0..1]</code>).</p>"}, {"id": "FIG-87f3e0105d2e8111", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR-Metamodell-Spezifikation (TPS_StandardizationTemplate). Es illustriert das Blueprint-Muster am Beispiel von <code>PortInterface</code>, bei dem dieselbe Metaklasse sowohl als Vorlage (<code>AtpBlueprint</code>) als auch als abgeleitetes Element (<code>AtpBlueprintable</code>) fungiert, sowie deren Verknüpfung über das generische und das konkrete Blueprint-Mapping.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>AtpBlueprintMapping</code>: Abstrakte Metaklasse für das Mapping zwischen Blueprints und abgeleiteten Objekten.</li>\n<li>Assoziation <code>+/atpBlueprint 1</code> («atpAbstract,atpUriDef») zu <code>AtpBlueprint</code>.</li>\n<li>Assoziation <code>+/atpBlueprintedElement 1</code> («atpAbstract») zu <code>AtpBlueprintable</code>.</li>\n<li><code>BlueprintMapping</code>: Konkrete Spezialisierung von <code>AtpBlueprintMapping</code>.</li>\n<li>Assoziation <code>+blueprint 1 {redefines atpBlueprint}</code> zu <code>AtpBlueprint</code>.</li>\n<li>Assoziation <code>+derivedObject 1 {redefines atpBlueprintedElement}</code> zu <code>AtpBlueprintable</code>.</li>\n<li><code>AtpBlueprint</code>: Abstraktes Konzept (spezialisiert <code>Identifiable</code>), Ziel der Blueprint-Referenz.</li>\n<li><code>AtpBlueprintable</code>: Abstraktes Konzept (spezialisiert <code>Identifiable</code>), Ziel der Referenz auf das abgeleitete Objekt.</li>\n<li><code>PortInterface</code>: Konkrete Metaklasse (spezialisiert <code>ARElement</code>, <code>AtpType</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>).</li>\n<li>Attribute:</li>\n<li><code>+ isService: Boolean [0..1]</code></li>\n<li><code>+ serviceKind: ServiceProviderEnum [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamischer Ablauf oder Sequenzverhalten dargestellt. Die Beziehungen definieren die strukturelle Bindung, mit der ein konkretes <code>BlueprintMapping</code> eine Instanz von <code>PortInterface</code> in der Rolle des Blueprints (<code>blueprint</code>) mit einer Instanz von <code>PortInterface</code> in der Rolle des abgeleiteten Objekts (<code>derivedObject</code>) verknüpft.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Muster für Werkzeughersteller und Standardisierer: <code>PortInterface</code> implementiert gleichzeitig <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Ein konkretes <code>BlueprintMapping</code> bindet per Redefinition die abstrakten Metarollen <code>atpBlueprint</code> und <code>atpBlueprintedElement</code> jeweils mit Kardinalität 1 an die Schnittstelleninstanzen. Die Attribute <code>isService</code> (<code>Boolean [0..1]</code>) und <code>serviceKind</code> (<code>ServiceProviderEnum [0..1]</code>) sind jeweils optional spezifiziert.</p>"}], "trans": [{"from": "FIG-2183ccd2503e7934", "to": "FIG-f24e73811509874a", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f24e73811509874a", "to": "FIG-4f47c59dfb7666ef", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4f47c59dfb7666ef", "to": "FIG-6dbd3d7ed2d85c1b", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6dbd3d7ed2d85c1b", "to": "FIG-87f3e0105d2e8111", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>In Klasse <code>PortInterface</code> wurde die Multiplizität des Attributs <code>isService: Boolean</code> von obligatorisch (<code>[1]</code>, implizit) auf optional <code>[0..1]</code> geändert.</li>\n</ul>"}]};
